<script setup>
import {computed,inject,ref} from 'vue';
import {useRoute} from 'vue-router';
import {watchVisibleReport} from '../../../lib/cc-visible-report';
import {requestVisitReport} from '../../../api/cc-visit-report';
import {printReportTable} from '../../../lib/cc-report-print';
import {consultantRollingRange} from '../../../lib/cc-report-financials';
import {agentReportKey} from '../../../lib/cc-agent-report-context';
import {branchOf,downloadCsv,maskPhone,visitStatus} from '../../../lib/cc';
import CCDataTable from '../CCDataTable.vue';
const {financial,financialLoading,financialError,loadFinancial,applied,printReport,openLead}=inject(agentReportKey);
const route=useRoute(),history=ref(null),historyBusy=ref(false),historyError=ref('');
async function loadHistory(){if(!applied.value)return;const [from_date,to_date]=consultantRollingRange(applied.value.to_date);historyBusy.value=true;historyError.value='';try{history.value=await requestVisitReport({view:'consultants',from_date,to_date});}catch(e){historyError.value=e.message;}finally{historyBusy.value=false;}}
const mode=ref('consultant'),branch=ref(''),query=ref(''),detail=ref(null),detailTitle=ref('');
watchVisibleReport(()=>[applied.value?.to_date],()=>route.meta.reportTab==='consultants'&&mode.value==='manager'&&!!applied.value,loadHistory,()=>!!history.value&&!historyError.value);
const appointments=computed(()=>(financial.value?.consultant_appointments||[]).filter(r=>(!branch.value||branchOf(r)===branch.value)&&(!query.value||[r.lead_name,r.consultant_name,r.manager_name,branchOf(r)].some(v=>String(v||'').toLowerCase().includes(query.value.toLowerCase())))&&String(r.custom_appointment_date_and_time).slice(0,10)>=applied.value?.from_date&&String(r.custom_appointment_date_and_time).slice(0,10)<=applied.value?.to_date));
const invoices=computed(()=>financial.value?.cc_invoice_report_summary?.rows||[]);
function stats(rows){const names=new Set(rows.map(r=>r.name));const invoiceRows=invoices.value.filter(r=>names.has(r.lead));const booked=rows.filter(r=>visitStatus(r)==='Visited-BKD').length,notBooked=rows.filter(r=>visitStatus(r)==='Visited-Not BKD').length;return {appointments:rows.length,pending:rows.filter(r=>visitStatus(r)==='Visited').length,visits:booked+notBooked,booked,notBooked,noShow:rows.filter(r=>visitStatus(r)==='Not Visited').length,with_gst:invoiceRows.reduce((n,r)=>n+Number(r.with_gst||0),0),without_gst:invoiceRows.reduce((n,r)=>n+Number(r.without_gst||0),0),paid:invoiceRows.reduce((n,r)=>n+Number(r.paid_with_gst??r.paid??0),0),balance:invoiceRows.reduce((n,r)=>n+Number(r.balance||0),0),conversion:booked+notBooked?Math.round(booked/(booked+notBooked)*100):0};}
const totals=computed(()=>stats(appointments.value));
const grouped=computed(()=>{const groups=new Map();for(const row of appointments.value){if(mode.value==='consultant'&&!row.consultant_eligible)continue;const name=mode.value==='manager'?row.manager_name:row.consultant_name;const key=branchOf(row)+'|'+name;if(!groups.has(key))groups.set(key,{key,name,branch:branchOf(row),designation:mode.value==='manager'?'Manager':row.consultant_designation,rows:[]});groups.get(key).rows.push(row);}return [...groups.values()].map(g=>({...g,teamCount:new Set(g.rows.filter(row=>row.consultant_eligible).map(row=>row.consultant_id)).size,...stats(g.rows),threeMonthAverage:history.value&&!history.value.truncated?Math.round((history.value.consultant_appointments||[]).filter(row=>branchOf(row)===g.branch&&row.manager_name===g.name).length/3*10)/10:null})).sort((a,b)=>a.branch.localeCompare(b.branch)||a.name.localeCompare(b.name));});
const metricLabels=[['appointments','Consultant Appointments'],['pending','Visit But Pending In Branch'],['visits','Total Visit Count'],['booked','Booked'],['notBooked','Not Booked'],['noShow','Not Visited'],['with_gst','New Package With GST'],['without_gst','New Package Without GST'],['paid','New Package Paid'],['balance','New Package Balance'],['conversion','Booking Conversion']];
const columns=computed(()=>[{key:'branch',label:'Branch'},{key:'name',label:mode.value==='manager'?'Manager':'Consultant'},{key:'designation',label:mode.value==='manager'?'Team Members':'Designation',value:row=>mode.value==='manager'?row.teamCount:row.designation},...metricLabels.map(([key,label])=>({key,label})),...(mode.value==='manager'?[{key:'threeMonthAverage',label:'3 Month Avg Appointment',value:r=>r.threeMonthAverage??'—'}]:[])]);
const detailColumns=[{key:'name',label:'Lead ID'},{key:'lead_name',label:'Client'},{key:'mobile_no',label:'Mobile',value:r=>maskPhone(r.mobile_no)},{key:'custom_appointment_date_and_time',label:'Appointment'},{key:'consultant_name',label:'Consultant'},{key:'manager_name',label:'Manager'},{key:'consultant_basis',label:'Attribution'},{key:'status',label:'Outcome',value:visitStatus}];
function show(rows,title,key){detailTitle.value=title;const predicates={pending:r=>visitStatus(r)==='Visited',visits:r=>['Visited-BKD','Visited-Not BKD'].includes(visitStatus(r)),booked:r=>visitStatus(r)==='Visited-BKD',notBooked:r=>visitStatus(r)==='Visited-Not BKD',noShow:r=>visitStatus(r)==='Not Visited'};detail.value=predicates[key]?rows.filter(predicates[key]):rows;}
const monetary=key=>['with_gst','without_gst','paid','balance'].includes(key);
</script>
<template><section class="cc-consultant-report"><header class="cc-consultant-head"><div><h2>👥 Consultant / Manager Report</h2><p>Appointments · branch visits · new package collections</p></div><button @click="printReportTable('Consultant / Manager Report',columns,grouped)">🖨 Print / PDF</button></header><div class="cc-report-tools"><button :aria-pressed="mode==='consultant'" @click="mode='consultant'">Employee-wise</button><button :aria-pressed="mode==='manager'" @click="mode='manager'">Manager-wise</button><label>Branch<select v-model="branch"><option value="">All permitted branches</option><option v-for="b in [...new Set((financial?.consultant_appointments||[]).map(branchOf))].sort()" :key="b">{{b}}</option></select></label><label>Search<input v-model="query" placeholder="Client, consultant, manager, branch"></label><button @click="branch='';query=''">Reset</button></div>
<p v-if="financialLoading" role="status">Loading consultant report…</p><p v-if="financialError" class="cc-error">{{financialError}} <button @click="loadFinancial">Retry</button></p>
<div class="kgrid consultant-report-kpis"><button v-for="[key,label] in metricLabels" :key="key" class="kpi" @click="show(appointments,label,key)"><b>{{monetary(key)?'₹':''}}{{Number(totals[key]||0).toLocaleString('en-IN')}}{{key==='conversion'?'%':''}}</b><span>{{label}}</span></button></div>
<p v-if="appointments.some(r=>!r.consultant_eligible)" class="cc-note">{{appointments.filter(r=>!r.consultant_eligible).length}} appointments have no active consultant mapping. They remain included in top totals.</p>
<p v-if="mode==='manager'&&historyBusy" role="status">Loading three-month manager averages…</p><p v-if="mode==='manager'&&historyError" role="alert">{{historyError}} <button @click="loadHistory">Retry comparison</button></p><p v-if="mode==='manager'&&history?.truncated" role="alert">Historical range is partial. Narrow the period; averages are withheld.</p><CCDataTable :columns="columns" :rows="grouped"><template #cell-notBooked="{row}"><button @click="show(row.rows,row.name+' · Visited – Not Booked','notBooked')">{{row.notBooked}}</button></template><template #cell-noShow="{row}"><button @click="show(row.rows,row.name+' · Not Visited','noShow')">{{row.noShow}}</button></template><template #actions="{row}"><button @click="show(row.rows,row.name)">Client details</button></template></CCDataTable><button @click="downloadCsv('consultant-'+mode+'.csv',columns,grouped)">⬇ Export CSV</button>
<dialog :open="detail!==null" class="cc-report-dialog cc-consultant-details"><header><h2>{{detailTitle}}</h2><button @click="detail=null">Close</button></header><CCDataTable :columns="detailColumns" :rows="detail||[]"><template #actions="{row}"><button @click="openLead(row.name)">Open lead</button></template></CCDataTable><button @click="downloadCsv('consultant-clients.csv',detailColumns,detail||[])">Export details</button></dialog>
</section></template>
<style scoped src="../../../styles/cc-agent-report.css"></style>
<style scoped>.cc-consultant-head{display:flex;gap:12px;align-items:center;justify-content:space-between}.kgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:10px;margin:14px 0}.kpi{display:grid;gap:6px;text-align:left;background:#fffdf5;border:1px solid #d5b66b;border-top:3px solid #236e4c;border-radius:9px;padding:16px;color:#16402d;font:inherit;cursor:pointer}.kpi b{font-size:24px}.kpi span{font-size:12px}.cc-consultant-details{position:fixed;inset:10vh auto auto 50%;transform:translateX(-50%);z-index:1000;box-shadow:0 0 0 100vmax #102c2266}</style>
